{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    allocations = [s['minimum'] for s in segments]
    capacities = [s['capacity'] for s in segments]
    importances = [s['importance'] for s in segments]
    remaining = budget - sum(allocations)
    if remaining < 0:
        raise ValueError('Budget below total minimum')
    total_cap = sum(capacities)
    if budget > total_cap:
        raise ValueError('Budget exceeds total capacity')
    while remaining > 0:
        best_idx = -1
        best_ratio = -1.0
        for i in range(n):
            if allocations[i] >= capacities[i]:
                continue
            ratio = importances[i] / (allocations[i] + 1)
            if ratio > best_ratio:
                best_ratio = ratio
                best_idx = i
        if best_idx == -1:
            break
        allocations[best_idx] += 1
        remaining -= 1
    total = sum(allocations)
    by_name = {segments[i]['name']: allocations[i] for i in range(n)}
    return {'allocations': allocations, 'by_name': by_name, 'total': total}"
}
